// JVM Flags:
// -XX:+UseZGC -XX:+ZGenerational -Xms32g -Xmx32g -XX:+AlwaysPreTouch
// -XX:+PerfDisableSharedMem -Xlog:gc*,safepoint:file=/var/log/gc.log:time,uptime

public final class FencedLeaderClient {
    public record Lease(long fencingToken, long expiresAtNano) {}
    private volatile Lease currentLease = new Lease(-1L, 0L);

    public void renewLease(long ttlNs) {
        long sendNano = System.nanoTime(); // Anchor BEFORE RPC!
        long token = etcdRenewRpc(ttlNs);
        if (token > 0) {
            this.currentLease = new Lease(token, sendNano + ttlNs);
        }
    }

    public void fencedWrite(String key, String value) {
        Lease lease = this.currentLease;
        if (System.nanoTime() > lease.expiresAtNano() - 500_000_000L) {
            throw new IllegalStateException("Local lease near expiry; stepping down");
        }
        int updated = executeSql(
            "UPDATE kv_store SET val = ?, fencing_token = ? WHERE k = ? AND fencing_token <= ?",
            value, lease.fencingToken(), key, lease.fencingToken()
        );
        if (updated == 0) {
            this.currentLease = new Lease(-1L, 0L);
            throw new IllegalStateException("Fenced out by newer leader");
        }
    }
}

